import java.util.Arrays;

final class Plot {
    private static void place(char[] band, double position, char symbol) { band[(int)Math.clamp(position, 0, 60)] = symbol; }
    private static char[] newBand() { char[] band = new char[61]; Arrays.fill(band, '.'); return band; }
    private static char[] framed(double center) {
        char[] band = newBand(); place(band, 0, ':'); place(band, 60, ':'); place(band, center, '|'); return band;
    }
    static String limitsBand(Limits limits, double value, boolean signalled) {
        double span = limits.ucl() - limits.lcl();
        char[] band = framed(Math.floor(60 * ((limits.cl() - limits.lcl()) / span) + 0.5));
        place(band, Math.floor(60 * ((value - limits.lcl()) / span) + 0.5), signalled ? '*' : 'o');
        return new String(band);
    }
    static String cusumBand(double upper, double lower, double threshold, boolean upperSignal, boolean lowerSignal) {
        char[] band = framed(30);
        if (lower > 0) place(band, 30 - Math.min(30, Math.floor(30 * (lower / threshold) + 0.5)), lowerSignal ? '*' : '-');
        if (upper > 0) place(band, 30 + Math.min(30, Math.floor(30 * (upper / threshold) + 0.5)), upperSignal ? '*' : '+');
        return new String(band);
    }
    static String widthBand(double scale, double width, double value, double center, boolean signalled) {
        char[] band = newBand();
        double edge = Math.min(30, Math.floor(30 * (width / scale) + 0.5));
        place(band, 30, '|'); place(band, 30 - edge, ':'); place(band, 30 + edge, ':');
        double deviation = (value - center) / scale;
        place(band, 30 + Math.floor(30 * deviation + 0.5), signalled ? '*' : 'o');
        return new String(band);
    }
    static String standardBand(double z, boolean ok) {
        char[] band = framed(30); place(band, 30 + Math.floor(10 * z + 0.5), ok ? 'o' : '*'); return new String(band);
    }
}

import java.util.ArrayList;
import java.util.List;

record Series(List<Integer> numbers, List<Double> values) {
    Series() { this(new ArrayList<>(), new ArrayList<>()); }
}
record Signal(int chart, int rule, int start, int end, double value, String direction) {}
final class Zones {
    final double lcl, cl, ucl, u1, u2, l1, l2;
    Zones(Limits limits) {
        lcl = limits.lcl(); cl = limits.cl(); ucl = limits.ucl();
        double upper = (ucl - cl) / 3, lower = (cl - lcl) / 3;
        u1 = cl + upper; u2 = cl + 2 * upper; l1 = cl - lower; l2 = cl - 2 * lower;
    }
    String name(double v) { return v > ucl ? "OUT+" : v < lcl ? "OUT-" : v > u2 ? "A+" : v > u1 ? "B+" : v > cl ? "C+" : v < l2 ? "A-" : v < l1 ? "B-" : v < cl ? "C-" : "C0"; }
}
final class RunRules {
    private static final int[] LENGTHS = {0, 1, 3, 5, 8, 6, 14, 15, 8};
    static List<Signal> check(int chart, Series series, Limits limits, List<Integer> rules) {
        Zones z = new Zones(limits);
        List<Signal> signals = new ArrayList<>();
        List<Double> v = series.values();
        for (int k = 1; k <= v.size(); k++) for (int rule : rules) {
            int length = LENGTHS[rule], first = k - length;
            if (first < 0) continue;
            double last = v.get(k - 1);
            String direction = null;
            List<Double> window = v.subList(first, k);
            if (rule == 1) {
                if (limits.outside(last)) direction = last > z.cl ? "UP" : "DOWN";
            } else if (rule == 2 || rule == 3) {
                double upper = rule == 2 ? z.u2 : z.u1, lower = rule == 2 ? z.l2 : z.l1;
                int needed = rule == 2 ? 2 : 4;
                if (last > upper && window.stream().filter(x -> x > upper).count() >= needed) direction = "UP";
                else if (last < lower && window.stream().filter(x -> x < lower).count() >= needed) direction = "DOWN";
            } else if (rule == 4) {
                if (window.stream().allMatch(x -> x > z.cl)) direction = "UP";
                else if (window.stream().allMatch(x -> x < z.cl)) direction = "DOWN";
            } else if (rule == 5) {
                boolean up = true, down = true;
                for (int j = first + 1; j < k; j++) { up &= v.get(j) > v.get(j - 1); down &= v.get(j) < v.get(j - 1); }
                if (up) direction = "UP"; else if (down) direction = "DOWN";
            } else if (rule == 6) {
                boolean valid = true;
                for (int j = first + 1; j < k; j++) {
                    if (v.get(j).doubleValue() == v.get(j - 1).doubleValue()) valid = false;
                    if (j > first + 1 && (v.get(j) > v.get(j - 1)) == (v.get(j - 1) > v.get(j - 2))) valid = false;
                }
                if (valid) direction = "NONE";
            } else if (rule == 7) {
                if (window.stream().allMatch(x -> x > z.l1 && x < z.u1)) direction = "NONE";
            } else if (window.stream().allMatch(x -> x > z.u1 || x < z.l1) && window.stream().anyMatch(x -> x > z.u1) && window.stream().anyMatch(x -> x < z.l1)) direction = "NONE";
            if (direction != null) signals.add(new Signal(chart, rule, series.numbers().get(first), series.numbers().get(k - 1), last, direction));
        }
        return signals;
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

record Limits(double lcl, double cl, double ucl) {
    boolean outside(double value) { return value > ucl || value < lcl; }
}
final class Subgroup {
    final int number;
    final long[] values;
    final long total, squares, range;
    final double mean, sd;
    Subgroup(int number, long[] values) {
        this.number = number; this.values = values;
        long sum = 0, sumSquares = 0;
        for (long value : values) { sum += value; sumSquares += value * value; }
        total = sum; squares = sumSquares;
        int n = values.length;
        mean = (double)total / n; range = Arrays.stream(values).max().orElseThrow() - Arrays.stream(values).min().orElseThrow();
        sd = Math.sqrt((double)(n * squares - total * total) / (n * (n - 1)));
    }
}
final class VariableCharts {
    static List<Subgroup> statistics(long[] values, int size) {
        List<Subgroup> groups = new ArrayList<>();
        for (int start = 0; start < values.length; start += size) groups.add(new Subgroup(start / size + 1, Arrays.copyOfRange(values, start, start + size)));
        return groups;
    }
    static Limits[] compute(int family, List<Integer> numbers, long[] values, List<Subgroup> groups, int size, Constants c) {
        long total = 0, ranges = 0;
        double deviations = 0;
        if (family == 2) {
            for (int number : numbers) total += values[number - 1];
            for (int j = 1; j < numbers.size(); j++) ranges += Math.abs(values[numbers.get(j) - 1] - values[numbers.get(j - 1) - 1]);
            double mean = (double)total / numbers.size(), range = (double)ranges / (numbers.size() - 1);
            Constants pair = Dataset.controlConstants(2);
            return new Limits[]{new Limits(mean - 3 * range / pair.d2(), mean, mean + 3 * range / pair.d2()), new Limits(pair.d3() * range, range, pair.d4() * range)};
        }
        for (int number : numbers) {
            Subgroup group = groups.get(number - 1);
            total += group.total; ranges += group.range; deviations += group.sd;
        }
        double mean = (double)total / (numbers.size() * size);
        double spread = family == 0 ? (double)ranges / numbers.size() : deviations / numbers.size();
        double factor = family == 0 ? c.a2() : c.a3();
        return new Limits[]{new Limits(mean - factor * spread, mean, mean + factor * spread), new Limits((family == 0 ? c.d3() : c.b3()) * spread, spread, (family == 0 ? c.d4() : c.b4()) * spread)};
    }
}
